// ── source: vcx/tests/http_chunked_stream_test.v ──
// http_chunked_stream_test.v — BEHAVIORAL conformance for the §3.5 server-side
// Transfer-Encoding: chunked WRITE path (the streaming-binary-response transport
// that the CSRP cx-store:// remote protocol reads back, GH #90 → #78).
//
// http.md §4.2 previously DEFERRED streaming responses: the server only wrote
// whole-body Content-Length responses. This test drives the new chunked-write
// path over a REAL loopback socket end to end:
//   * a cx program is the SERVER — it reads the POST request body as raw octets
//     ([$http:body-bytes]) and returns it as a `Transfer-Encoding: chunked`
//     response (no Content-Length);
//   * a raw-socket V client POSTs a >8 KB BINARY payload (every non-NUL byte
//     value, forcing multiple 4 KB wire chunks), reads the reply, de-chunks it,
//     and asserts the recovered octets are byte-identical to what it sent.
//
// A stub cannot do this: byte-identity across a chunked round trip proves the
// request body was read off the wire AND the response was framed as real
// multi-chunk chunked-transfer-encoding the peer must reassemble.

fn cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint PID + nanosecond-salted band (26500-26599) so the concurrent
// `v test vcx/tests/` gate processes don't collide on a port.
fn pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26500 + int(salt)
}

fn write_tmp(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// The cx low-level server: bind, accept, and for each exchange echo the request
// body back as a Transfer-Encoding: chunked 200 response. body-bytes preserves
// raw octets; the chunked header drives http_serialize_response's streaming path.
fn server_prog(port int) string {
	return '[?lib \'cx-stdlib/http\' :as http]\n' +
		'[?let [= \$srv [\$http:listen "tcp://127.0.0.1:${port}" {}]]\n' +
		'  [?for [in \$ex [\$http:accept-iter \$srv]]\n' +
		'    [yield [?let [= \$req [\$http:exchange-request \$ex]]\n' +
		'      [?let [= \$b [\$http:body-bytes \$req]]\n' +
		'        [\$http:respond \$ex [response status=200\n' +
		'          [headers [header name="Transfer-Encoding" value="chunked"]]\n' +
		'          [body \$b]]]]]]]]\n'
}

// A >8 KB binary payload: every byte value 1..255 repeated, so the server must
// split it into multiple http_chunk_size (4096) wire chunks.
fn binary_payload() []u8 {
	mut p := []u8{}
	for _ in 0 .. 42 {
		for v in 1 .. 256 {
			p << u8(v)
		}
	}
	return p
}

// dechunk strips HTTP/1.1 chunked transfer-encoding framing: each chunk is
// `<hex-len>\r\n<bytes>\r\n`, terminated by a 0-length chunk.
fn dechunk(raw []u8) []u8 {
	mut out := []u8{}
	mut pos := 0
	for pos < raw.len {
		mut le := pos
		for le + 1 < raw.len && !(raw[le] == `\r` && raw[le + 1] == `\n`) {
			le++
		}
		if le + 1 >= raw.len {
			break
		}
		hexs := raw[pos..le].bytestr().all_before(';').trim_space()
		mut size := 0
		for c in hexs {
			d := if c >= `0` && c <= `9` {
				int(c - `0`)
			} else if c >= `a` && c <= `f` {
				int(c - `a` + 10)
			} else if c >= `A` && c <= `F` {
				int(c - `A` + 10)
			} else {
				break
			}
			size = size * 16 + d
		}
		data := le + 2
		if size == 0 {
			break
		}
		if data + size > raw.len {
			break
		}
		out << raw[data..data + size]
		pos = data + size + 2
	}
	return out
}

fn raw_round_trip(port int, body []u8) (bool, []u8) {
	for _ in 0 .. 40 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		head := 'POST /echo HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: ${body.len}\r\nConnection: close\r\n\r\n'
		mut req := head.bytes()
		req << body
		c.write(req) or {
			c.close() or {}
			return false, []u8{}
		}
		c.set_read_timeout(5 * time.second)
		mut sink := []u8{}
		mut buf := []u8{len: 4096}
		for {
			n := c.read(mut buf) or { break }
			if n <= 0 {
				break
			}
			sink << buf[..n]
			if sink.len > 1048576 {
				break
			}
		}
		c.close() or {}
		return true, sink
	}
	return false, []u8{}
}

fn test_http_server_chunked_binary_stream() {
	port := pick_port()
	prog := write_tmp('cx_http_chunked.cx', server_prog(port))
	out_file := '/tmp/cx-http-chunked.${port}.out'
	pid_s := os.execute('${cx_binary()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx http server')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	time.sleep(400 * time.millisecond) // let the server bind

	payload := binary_payload()
	connected, resp := raw_round_trip(port, payload)
	srv_log := os.read_file(out_file) or { '' }
	assert connected, 'cx http server never accepted a connection on ${port}; server log: ${srv_log}'

	rs := resp.bytestr()
	he := rs.index('\r\n\r\n') or {
		assert false, 'no header terminator in response; got ${resp.len} bytes | server log: ${srv_log}'
		return
	}
	head := rs[..he]
	assert head.contains('200'), 'response missing 200 status; head: ${head}'
	// The streaming path MUST advertise chunked and MUST NOT set Content-Length.
	assert head.to_lower().contains('transfer-encoding: chunked'), 'response not chunked; head: ${head}'
	assert !head.to_lower().contains('content-length'), 'chunked response must not carry Content-Length; head: ${head}'
	// And it must terminate with a 0-length chunk.
	assert rs.ends_with('0\r\n\r\n'), 'chunked response missing 0-length terminator; tail bytes: ${resp.len}'

	body_wire := resp[he + 4..]
	recovered := dechunk(body_wire)
	assert recovered.len == payload.len, 'de-chunked length ${recovered.len} != sent ${payload.len} (server log: ${srv_log})'
	assert recovered == payload, 'binary stream not byte-identical after chunked round trip'
	// The payload is >8 KB, so it had to span multiple 4 KB wire chunks — assert
	// the framing actually streamed (more than one chunk header present).
	assert payload.len > 8192, 'payload too small to force multiple chunks'
}

// ── source: vcx/tests/http_client_timeout_test.v ──
// http_client_timeout_test.v — BEHAVIORAL guard for the §4.5 whole-request
// client timeout (cx-private #275; spec/03-approved/std-lib/http.md §3.1/§4.5).
//
// The net layer alone cannot bound a request: connect is select-bounded (5s)
// and each single read has a 30s socket default, but a response that keeps
// DRIBBLING bytes resets the per-read clock on every arrival — an LLM upstream
// streaming a generation held a connection (and, served inline, its reactor —
// the #275 helm wedge) for minutes with no single read ever timing out. Only a
// whole-request budget bounds that, surfaced as CXER4534 E_HTTP_REQUEST_TIMEOUT.
//
// Each test runs a raw V TCP server with a pathological behavior and asserts
// the cx one-shot client (through the real CLI + capability layer) fails with
// CXER4534 promptly — or, for the control, succeeds.

fn cx_bin() string {
	return testenv.cx_bin()
}

// run_fixture evaluates one [$http:get] against 127.0.0.1:port with the given
// timeout opt and returns (combined output, wall ms).
fn run_fixture(port int, timeout_opt string) (string, i64) {
	prog := "[?lib 'cx-stdlib/http' :as http]\n" +
		'[\$http:get "http://127.0.0.1:${port}/" {timeout: ${timeout_opt}}]'
	dir := os.join_path(os.temp_dir(), 'cx_275_timeout_${os.getpid()}_${port}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	src := os.join_path(dir, 'req.cx')
	os.write_file(src, prog) or { panic('write: ${err}') }
	t0 := time.ticks()
	res := os.execute('${cx_bin()} --allow-net=127.0.0.1 ${os.quoted_path(src)} 2>&1')
	return res.output, time.ticks() - t0
}

// Server loops exit on the first accept error — each test closes its listener
// when done, which ends its server thread cleanly (an `or { continue }` retry
// here spins hot on the closed listener for the rest of the process).

// blackhole: accept, read the request, never write a byte.
fn serve_blackhole(mut l net.TcpListener) {
	for {
		mut c := l.accept() or { return }
		spawn fn (mut c net.TcpConn) {
			mut buf := []u8{len: 4096}
			c.read(mut buf) or {}
			time.sleep(3 * time.second) // hold the conn silent past the test's budget
			c.close() or {}
		}(mut c)
	}
}

// dribble: valid headers with a huge Content-Length, then one body byte every
// 100ms — every read succeeds, so ONLY a whole-request budget can stop it.
fn serve_dribble(mut l net.TcpListener) {
	for {
		mut c := l.accept() or { return }
		spawn fn (mut c net.TcpConn) {
			mut buf := []u8{len: 4096}
			c.read(mut buf) or {}
			c.write_string('HTTP/1.1 200 OK\r\nContent-Length: 1000000\r\n\r\n') or {
				c.close() or {}
				return
			}
			for _ in 0 .. 50 {
				c.write_string('x') or { break }
				time.sleep(100 * time.millisecond)
			}
			c.close() or {}
		}(mut c)
	}
}

// ok: a normal, prompt 200 per connection.
fn serve_ok(mut l net.TcpListener) {
	for {
		mut c := l.accept() or { return }
		mut buf := []u8{len: 4096}
		c.read(mut buf) or {}
		c.write_string('HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok') or {}
		c.close() or {}
	}
}

fn listen_local() (&net.TcpListener, int) {
	mut l := net.listen_tcp(.ip, '127.0.0.1:0') or { panic('listen: ${err}') }
	addr := l.addr() or { panic('addr: ${err}') }
	return l, addr.port() or { panic('port: ${err}') }
}

fn test_blackhole_times_out_with_cxer4534() {
	mut l, port := listen_local()
	spawn serve_blackhole(mut l)
	out, wall := run_fixture(port, '500ms')
	l.close() or {}
	assert out.contains('CXER4534'), 'expected CXER4534 from a silent upstream, got: ${out}'
	assert wall < 10_000, 'timeout took ${wall}ms — not bounded by the 500ms budget'
}

fn test_dribbling_body_defeats_per_read_timeouts_but_not_the_budget() {
	mut l, port := listen_local()
	spawn serve_dribble(mut l)
	out, wall := run_fixture(port, '700ms')
	l.close() or {}
	assert out.contains('CXER4534'), 'expected CXER4534 from a dribbling upstream (whole-request budget), got: ${out}'
	assert wall < 10_000, 'dribble timeout took ${wall}ms — the per-read clock was reset instead of the request being bounded'
}

fn test_prompt_response_unaffected() {
	mut l, port := listen_local()
	spawn serve_ok(mut l)
	out, wall := run_fixture(port, '5s')
	l.close() or {}
	assert !out.contains('CXER4534'), 'prompt response wrongly timed out after ${wall}ms: ${out}'
	assert out.contains('200'), 'expected a 200 response, got: ${out}'
}

// ── source: vcx/tests/http_concurrent_sse_test.v ──
// http_concurrent_sse_test.v — #28: concurrent SSE push on the [$http:serve]
// path. A handler promotes GET /events to a held-open feed by returning
// `[sse-subscribe topic="…" [event …]?]`; any handler fans out with
// `[$http:sse-publish "…" [event …]]`. The reactor is never blocked — other
// requests (and other SSE feeds) are served concurrently while a feed is held.
//
// Asserts:
//   1. Two independent SSE clients both receive the initial frame.
//   2. A plain GET /ping returns promptly WHILE both feeds are held (the bug:
//      a held stream used to serialize the server).
//   3. After GET /push, BOTH feeds receive the published event (fan-out).
//   4. sse-publish reports the subscriber count it delivered to (2).

fn cx_bin_sse() string {
	return testenv.cx_bin()
}

fn pick_port_sse() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 28900 + int(salt)
}

fn sse_server_prog(port int) string {
	return "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?def h impure (\$req)\n' +
		'  [?let [= \$p [\$text \$req@path]]\n' +
		'    [?if [= \$p "/events"]\n' +
		'      [then [sse-subscribe topic="prices" [event data="hello"]]]\n' +
		'      [else [?if [= \$p "/push"]\n' +
		'        [then [?let [= \$n [\$http:sse-publish "prices" [event data="tick-42"]]]\n' +
		'                [response status=200 [body [\$concat "pushed=" [\$text \$n]]]]]]\n' +
		'        [else [response status=200 [body "pong"]]]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]\n'
}

// open an SSE subscriber connection and return the socket
fn open_sse(port int) ?&net.TcpConn {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return none }
	c.write_string('GET /events HTTP/1.1\r\nHost: x\r\n\r\n') or { return none }
	c.set_read_timeout(4 * time.second)
	return c
}

// a one-shot GET returning the response body, measuring round-trip ms. Reads
// exactly the Content-Length body and returns — does NOT wait for the socket
// close (the server advertises Connection: close but defers the actual close to
// its idle path; waiting for EOF would measure that, not response latency).
fn get_body(port int, path string) (string, f64) {
	t0 := time.now()
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return '', 0.0 }
	defer { c.close() or {} }
	c.write_string('GET ${path} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n') or { return '', 0.0 }
	c.set_read_timeout(4 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	mut want := -1
	mut head_end := -1
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		resp_now := raw.bytestr()
		if head_end < 0 {
			head_end = resp_now.index('\r\n\r\n') or { -1 }
			if head_end >= 0 {
				for line in resp_now[..head_end].split('\r\n') {
					if line.to_lower().starts_with('content-length:') {
						want = line.all_after(':').trim_space().int()
					}
				}
			}
		}
		if head_end >= 0 {
			have := raw.len - (head_end + 4)
			if want < 0 || have >= want {
				break
			}
		}
		if raw.len > 65536 {
			break
		}
	}
	ms := f64(time.now() - t0) / f64(time.millisecond)
	resp := raw.bytestr()
	idx := resp.index('\r\n\r\n') or { return resp, ms }
	body_all := resp[idx + 4..]
	if want >= 0 && body_all.len >= want {
		return body_all[..want], ms
	}
	return body_all, ms
}

// read whatever the SSE connection has so far (up to deadline / target)
fn read_sse(mut c net.TcpConn, target string) string {
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		if raw.bytestr().contains(target) || raw.len > 65536 {
			break
		}
	}
	return raw.bytestr()
}

fn test_concurrent_sse_push() {
	port := pick_port_sse()
	prog := os.join_path(os.temp_dir(), 'cx_sse28_${os.getpid()}.cx')
	os.write_file(prog, sse_server_prog(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-sse28.${port}.out'
	pid_s := os.execute('${cx_bin_sse()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx sse server')
		return
	}
	pid := pid_s.output.trim_space()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
		os.rm(out_file) or {}
	}

	// wait for the listener
	mut up := false
	for _ in 0 .. 50 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.close() or {}
		up = true
		break
	}
	assert up, 'cx sse server never came up on ${port}'

	// two SSE subscribers
	mut a := open_sse(port) or {
		assert false, 'could not open SSE client A'
		return
	}
	mut b := open_sse(port) or {
		assert false, 'could not open SSE client B'
		return
	}
	defer {
		a.close() or {}
		b.close() or {}
	}
	// Wait for BOTH subscriptions to actually register before pushing — don't
	// guess a duration. `sse-subscribe` writes each client's initial
	// [event data="hello"] frame ATOMICALLY with the subscriber registration,
	// under the topic-registry lock (cx_sse_topic_subscribe), so receiving that
	// frame IS the readiness ack: every publish issued after it must count this
	// subscriber. Blocking on it (read deadline 4s, set in open_sse) makes the
	// pushed=2 count deterministic under heavy parallel-test CPU load. History:
	// a fixed sleep here raced and intermittently saw pushed=1 (#124); the first
	// fix waited for the initial frame, but the runtime then wrote that frame
	// BEFORE registering the fd, so a publish on another reactor could still
	// slip into the gap — same intermittent pushed=1. If this assert ever
	// reports pushed=1 again, that ack/registration atomicity has regressed —
	// do not paper over it with a retry.
	init_a := read_sse(mut a, 'data: hello')
	assert init_a.contains('data: hello'), 'client A never received its initial frame (subscribe not registered): "${init_a}"'
	init_b := read_sse(mut b, 'data: hello')
	assert init_b.contains('data: hello'), 'client B never received its initial frame: "${init_b}"'

	// (2) a plain request returns PROMPTLY while both feeds are held — the
	// concurrency the bug denied. The pre-fix failure mode blocked until the
	// stream ENDED (~seconds); a concurrent server answers immediately. Under a
	// saturated CI box (the V suite runs ~12 compile/run jobs in parallel) a
	// single round-trip can spike past 1s purely from scheduler contention, even
	// though the server is concurrent — so take the BEST of three pings (a
	// serialized server would block ALL of them) and use a generous ceiling.
	// Every ping must still return the correct body WHILE the feeds are held.
	mut best_ping_ms := 1.0e9
	for _ in 0 .. 3 {
		ping_body, ping_ms := get_body(port, '/ping')
		assert ping_body.trim_space() == 'pong', 'ping not served while SSE held: "${ping_body}"'
		if ping_ms < best_ping_ms {
			best_ping_ms = ping_ms
		}
	}
	assert best_ping_ms < 2500.0, 'ping blocked ${best_ping_ms}ms (best of 3) while SSE feed held — not concurrent'

	// (3)/(4) publish fans out to both subscribers; the count is reported. Both
	// are confirmed-registered above (each got its initial frame), so this is
	// deterministically 2 — no longer a race against a fixed sleep.
	push_body, _ := get_body(port, '/push')
	assert push_body.contains('pushed=2'), 'sse-publish should report 2 subscribers, got: "${push_body}"'

	// (3) the pushed event reaches BOTH feeds. (The initial `data: hello` frame
	// was already consumed + asserted above as the subscription-readiness gate.)
	got_a := read_sse(mut a, 'tick-42')
	got_b := read_sse(mut b, 'tick-42')
	assert got_a.contains('data: tick-42'), 'client A missing pushed event: "${got_a}"'
	assert got_b.contains('data: tick-42'), 'client B missing pushed event: "${got_b}"'
}

// ── source: vcx/tests/http_handler_no_respond_test.v ──
// http_handler_no_respond_test.v — #23: an accept-iter handler that returns
// WITHOUT responding (e.g. a denied capability poisons the response argument, so
// [$http:respond] short-circuits on the err-value and never writes) must NOT
// leave the connection dangling with no diagnostic. The accept loop surfaces it
// on stderr and closes the connection so the client gets EOF instead of hanging.
//
// Drives a real cx server (denied --allow-env) over a loopback socket.

fn cx_bin_h23() string {
	return testenv.cx_bin()
}

fn pick_port_h23() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26500 + int(salt)
}

// Handler is a [?def] route called with a DENIED-env value as an argument.
// Under --allow-net only, [$env:var-or-default] yields a CXER0271 err-value;
// the call [$route $ex $k] then short-circuits on the err-value ARG (error-as-
// value propagation), so the route body — and its [$http:respond] — never run.
// The handler returns the err-value without responding: the #23 case.
fn server_prog_no_respond(port int) string {
	return "[?lib 'cx-stdlib/http' :as http]\n" + "[?lib 'cx-stdlib/env' :as env]\n" +
		'[?def route impure (\$ex \$k)\n' +
		'  [\$http:respond \$ex [response status=200 [body \$k]]]]\n' +
		'[?let [= \$k [\$env:var-or-default "SOME_VAR" "fallback"]]\n' +
		'      [= \$srv [\$http:listen "tcp://127.0.0.1:${port}" {}]]\n' +
		'  [?for [in \$ex [\$http:accept-iter \$srv]]\n' +
		'    [yield [\$route \$ex \$k]]]]\n'
}

fn test_handler_without_response_is_surfaced() {
	port := pick_port_h23()
	prog := os.join_path(os.temp_dir(), 'cx_h23_${os.getpid()}.cx')
	os.write_file(prog, server_prog_no_respond(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-h23.${port}.out'
	pid_s := os.execute('${cx_bin_h23()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx http server')
		return
	}
	pid := pid_s.output.trim_space()
	defer { os.execute('kill ${pid} 2>/dev/null') }

	mut connected := false
	for _ in 0 .. 40 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		connected = true
		c.write_string('POST /x HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: 3\r\nConnection: close\r\n\r\nabc') or {}
		// If the fix works the server CLOSES the connection, so this read
		// returns promptly with EOF rather than blocking to the timeout.
		c.set_read_timeout(3 * time.second)
		mut buf := []u8{len: 1024}
		c.read(mut buf) or {}
		c.close() or {}
		break
	}
	assert connected, 'could not connect to cx server on ${port}'
	time.sleep(200 * time.millisecond) // let the server flush its stderr
	log := os.read_file(out_file) or { '' }
	os.rm(out_file) or {}
	assert log.contains('without responding'),
		'expected the #23 fail-loud diagnostic (handler returned without responding); got: ${log}'
}

// ── source: vcx/tests/http_picoev_engine_test.v ──
// Increment-1 spike for the cx-native picoev + picohttpparser server leg
// (spec/02-inprogress/stdlib_http.md §9 backend note). This does NOT
// touch the production [?http-service] listener yet — it proves, in
// isolation, that:
//   • picoev + picohttpparser LINK and run under the patched V fork in
//     the `vcx` build context (nothing in cx has ever driven picoev),
//   • the top-level callback + `voidptr` user_data ABI we will use in
//     the production swap behaves as expected,
//   • a request parsed by picohttpparser round-trips a response a real
//     HTTP client can read.
// Once green, the production net.http listener
// (services_listener_notd_wasm32_emcc.v) is swapped onto this engine
// while keeping http_service_real_socket_test.v green.

// SpikeCtx is handed to the callback via picoev's user_data voidptr —
// the same mechanism the production engine uses to carry the
// per-service handler context across the C callback boundary.
struct SpikeCtx {
	payload string
}

// spike_callback is a TOP-LEVEL fn (no closure) so V's C-callback ABI
// gets a clean function pointer. It echoes the request path back in the
// body so the test can confirm picohttpparser actually parsed the line.
fn spike_callback(data voidptr, req picohttpparser.Request, mut res picohttpparser.Response) {
	ctx := unsafe { &SpikeCtx(data) }
	body := '${ctx.payload}:${req.method}:${req.path}'
	res.http_ok()
	res.plain()
	res.body(body)
	res.end()
}

// free_port returns a likely-free port on a disjoint PID + nanosecond-salted
// band (25000-25099) so the concurrent `v test vcx/tests/` gate processes don't
// collide — two same-nanosecond starts still differ via the PID term.
fn free_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 25000 + int(salt)
}

fn test_picoev_engine_links_and_serves() {
	port := free_port()
	ctx := &SpikeCtx{
		payload: 'pico-ok'
	}
	mut server := picoev.new(
		port:      port
		host:      '127.0.0.1'
		family:    net.AddrFamily.ip
		cb:        spike_callback
		user_data: ctx
	) or {
		assert false, 'picoev.new failed to bind 127.0.0.1:${port}: ${err}'
		return
	}
	// serve() blocks on its event loop; run it on its own thread. The
	// spike has no stop path — the thread is reclaimed at process exit
	// (stoppable serve lands with the production engine's [?stop] work).
	spawn server.serve()

	// Poll until the listener answers (bind + first accept are async).
	mut up := false
	for _ in 0 .. 30 {
		probe := http.get('http://127.0.0.1:${port}/__ping__') or {
			time.sleep(50 * time.millisecond)
			continue
		}
		if probe.status_code == 200 {
			up = true
			break
		}
	}
	assert up, 'picoev listener never answered on 127.0.0.1:${port}'

	// Confirm picohttpparser parsed the request line: method + path echo.
	resp := http.get('http://127.0.0.1:${port}/hello/world') or {
		assert false, 'GET failed: ${err}'
		return
	}
	assert resp.status_code == 200
	assert resp.body == 'pico-ok:GET:/hello/world', 'unexpected body: ${resp.body}'
}

// ── source: vcx/tests/http_query_params_test.v ──
// http_query_params_test.v — #627: a GET's URL query string reaches the
// handler as parsed [query-params] (the locked §2.2 shape: one
// [<name> "<value>"] child per pair, percent-decoded, `+` = space) on the
// socket-listener lane. Pre-fix the container arrived EMPTY and the raw query
// was unrecoverable — GET parameterization was impossible.

fn qp_port() int {
	// Disjoint band (25700-25799) from http_serve_module_test (25600-25699).
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 25700 + int(salt)
}

fn test_module_serve_populates_query_params() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	tmp := os.temp_dir()
	port := qp_port()
	prog := os.join_path(tmp, 'serve-qp-${time.now().unix_milli()}.cx')
	// the handler echoes two query params (one percent-encoded) plus the
	// count, proving the container is populated, decoded, and readable via
	// the terminal labeled-field unwrap.
	os.write_file(prog, '
[?lib \'cx-stdlib/http\']
[?def h (\$req::element)
  [response status=200
    [body [?str \'as={[?else \$req/query-params/as ""]}|role={[?else \$req/query-params/role ""]}|n={[\$count \$req/query-params/*]}\']]]]
[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]
') or { panic(err) }
	defer {
		os.rm(prog) or {}
	}
	cmd := '${testenv.cx_bin()} --allow-net ${prog} >/tmp/cx-serve-qp.${port}.out 2>&1 & echo $!'
	res := os.execute(cmd)
	if res.exit_code != 0 {
		panic('spawn failed: ${res.output}')
	}
	pid := res.output.trim_space().int()
	defer {
		os.execute('kill ${pid}')
	}
	mut waited := 0
	mut up := false
	for waited < 50 {
		probe := os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 1 "http://127.0.0.1:${port}/x"')
		if probe.exit_code == 0 && probe.output != '' && probe.output != '000' {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
		waited++
	}
	assert up, 'listener never bound: ${os.read_file('/tmp/cx-serve-qp.${port}.out') or { '(none)' }}'

	got := os.execute('curl -s --max-time 3 "http://127.0.0.1:${port}/pane/queue?as=amy&role=a%20e"')
	assert got.exit_code == 0, 'curl failed: ${got.output}'
	assert got.output.contains('as=amy'), 'query param `as` lost (#627): ${got.output}'
	assert got.output.contains('role=a e'), 'query param not percent-decoded: ${got.output}'
	assert got.output.contains('n=2'), 'query-params container wrong arity: ${got.output}'

	// no query → empty container, path routing unaffected
	none_got := os.execute('curl -s --max-time 3 "http://127.0.0.1:${port}/pane/queue"')
	assert none_got.output.contains('n=0'), 'query-less request must have an empty container: ${none_got.output}'
}

// ── source: vcx/tests/http_reactor_rss_bound_test.v ──
// http_reactor_rss_bound_test.v — BEHAVIORAL guard for cx-private #57.
//
// Root cause (CX side): the `[?for]` comprehension walker built each
// per-generator-item frame with `MatchEnv.clone()`, which DEEP-COPIES the whole
// `closures` table. In a `[?lib]`-loaded `$http:serve` handler that table holds
// the entire imported stdlib closure set, so an N-item `[?for]` copied it N
// times PER REQUEST. Under the shipped `-gc e` collector that transient
// high-water is held, so a handler that runs a modest comprehension grows to
// hundreds of MB on the first request (measured: a 200-item `[?for]` → ~660 MB,
// a 2000-item one → ~1.6 GB) and sustained traffic exhausts the heap →
// `V panic: memory allocation failure` (the reported OOM).
//
// Fix: the walker now uses `clone_frame_sharing_closures()`, which ALIASES the
// closures table (the same B17 optimization the closure-call path uses) instead
// of copying it. The same 200-item handler now holds at ~60 MB. This test drives
// a real loopback `$http:serve` whose handler runs a per-request comprehension,
// hammers it, and asserts (a) the process survives and (b) RSS stays well under
// a ceiling that cleanly separates the fixed path (~60 MB) from the pre-fix
// blow-up (660 MB+). It MUST run against the shipped `-gc e` build to be
// meaningful.

fn rss_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26600 + int(salt)
}

fn write_tmp_file(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// rss_kb reads the resident set size (KB) of `pid` via ps. Returns 0 when
// unmeasurable so the test can SKIP rather than fail spuriously.
fn rss_kb(pid int) u64 {
	r := os.execute('ps -o rss= -p ${pid}')
	if r.exit_code != 0 {
		return 0
	}
	return r.output.trim_space().u64()
}

// A handler that does real per-request transient allocation: a 200-item `[?for]`
// building short strings (mirrors the issue's "concat + [?for]" response build).
// Pre-fix this alone drove the per-request high-water to ~660 MB.
fn rss_server_prog(port int) string {
	return "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?def h impure (\$req)\n' +
		'  [?let [= \$rows [?for [in \$i [\$range 1 200]]\n' +
		'                    [yield [\$concat "row-" [\$text \$i] "=" [\$text [* \$i \$i]] ";"]]]]\n' +
		'    [response status=200 [body [\$concat "ok " [\$text [\$count \$rows]]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]\n'
}

// one_get fires a single GET and returns true once the full response (status
// line + Content-Length body) has been read. It must NOT wait for socket EOF —
// the reactor defers the connection close to its idle path, so reading to EOF
// would block the full read timeout on every request. Instead it parses
// Content-Length and returns as soon as the advertised body has arrived.
fn one_get(port int) bool {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return false }
	defer {
		c.close() or {}
	}
	c.write_string('GET / HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n') or { return false }
	c.set_read_timeout(4 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	mut head_end := -1
	mut want := -1
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		s := raw.bytestr()
		if head_end < 0 {
			head_end = s.index('\r\n\r\n') or { -1 }
			if head_end >= 0 {
				for line in s[..head_end].split('\r\n') {
					if line.to_lower().starts_with('content-length:') {
						want = line.all_after(':').trim_space().int()
					}
				}
			}
		}
		if head_end >= 0 {
			body_have := raw.len - (head_end + 4)
			if want < 0 || body_have >= want {
				break // full response in hand; don't wait for the deferred close
			}
		}
		if raw.len > 65536 {
			break
		}
	}
	return raw.bytestr().contains('200')
}

fn test_reactor_rss_bounded_under_sustained_for_comprehension() {
	port := rss_port()
	prog := write_tmp_file('cx_rss_srv.cx', rss_server_prog(port))
	pid_s := os.execute('${cx_bin()} --allow-all ${prog} >/tmp/cx_rss_srv.log 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	if pid <= 0 {
		eprintln('SKIP: could not spawn cx reactor server')
		return
	}
	defer {
		os.execute('kill -9 ${pid} 2>/dev/null')
	}

	// Wait for the listener to bind (first successful GET).
	mut up := false
	for _ in 0 .. 50 {
		if one_get(port) {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	if !up {
		log := os.read_file('/tmp/cx_rss_srv.log') or { '' }
		eprintln('SKIP: cx reactor never bound on ${port}; log: ${log}')
		return
	}

	// Drive a sustained run. Pre-fix the heap blew past the ceiling within a
	// handful of requests and eventually OOM-panicked; post-fix RSS plateaus.
	mut ok := 0
	for _ in 0 .. 500 {
		if one_get(port) {
			ok++
		}
	}

	// The server must still be alive (no OOM panic) ...
	alive := os.execute('kill -0 ${pid} 2>/dev/null').exit_code == 0
	log := os.read_file('/tmp/cx_rss_srv.log') or { '' }
	assert alive, 'reactor died under sustained polling (likely the #57 OOM panic); served ${ok}/500; log: ${log}'
	assert ok >= 450, 'reactor dropped too many requests: ${ok}/500 ok; log: ${log}'

	// ... and its RSS must stay far below the pre-fix blow-up. Fixed path holds
	// ~60 MB; pre-fix exceeded 660 MB after only ~30 requests. 300 MB cleanly
	// separates the two with generous platform headroom.
	rkb := rss_kb(pid)
	if rkb == 0 {
		eprintln('NOTE: RSS unmeasurable on this platform; survival assertions still hold')
		return
	}
	assert rkb < 300 * 1024, 'reactor RSS ${rkb} KB after 500 requests exceeds the 300 MB ceiling — the per-request closures-table copy regressed (#57); pre-fix this was 660 MB+'
}

// A heavier per-request value-building handler (1000-item [?for] → concat join),
// the cx-private #131 (xap-marine OOM) shape: large transient body building, a
// small steady live set. vgc's OLD fixed-floor pacer never fired on this pattern,
// so committed pages — and RSS — climbed monotonically (measured: ~571 MB and
// rising). The reactor churn gate (gc_collect_if_churned) held it flat as a
// host-side crutch; since cx #71 the vgc ADAPTIVE pacer bounds it by
// construction and the gate defaults OFF — so this test now guards the pacer
// itself (no CX_HTTP_GC_* env is set).
fn rss_heavy_server_prog(port int) string {
	return "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?def h impure (\$req)\n' +
		'  [?let [= \$rows [?for [in \$i [\$range 1 1000]]\n' +
		'                    [yield [\$concat "row-" [\$text \$i] "=" [\$text [* \$i \$i]] ";"]]]]\n' +
		'    [response status=200 [body [\$concat "ok " [\$text [\$count \$rows]]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]\n'
}

fn test_reactor_rss_bounded_under_heavy_value_building() {
	port := rss_port() + 1
	prog := write_tmp_file('cx_rss_heavy.cx', rss_heavy_server_prog(port))
	// Single reactor (CX_HTTP_N=1): RSS bounding is the concern here. Frequent
	// collection trips the known residual multi-reactor GC race (a SEPARATE
	// axis), so pin one reactor to keep this gate measuring RSS, not the race.
	pid_s := os.execute('CX_HTTP_N=1 ${cx_bin()} --allow-all ${prog} >/tmp/cx_rss_heavy.log 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	if pid <= 0 {
		eprintln('SKIP: could not spawn heavy reactor server')
		return
	}
	defer {
		os.execute('kill -9 ${pid} 2>/dev/null')
	}

	mut up := false
	for _ in 0 .. 50 {
		if one_get(port) {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	if !up {
		log := os.read_file('/tmp/cx_rss_heavy.log') or { '' }
		eprintln('SKIP: heavy reactor never bound on ${port}; log: ${log}')
		return
	}

	// Sustained heavy load, measured as CONVERGENCE: drive identical 1000-req
	// windows until one grows RSS by <10% over the previous window's end (the
	// pacer's steady state), bounded by a window budget and a hard absolute
	// backstop. The honest #71 contract is "plateaus by construction" — the
	// absolute equilibrium (and how fast it is reached) legitimately varies
	// with build opt-level AND with CPU contention from parallel test jobs
	// (both inflate GC pauses, so the adaptive headroom settles higher), which
	// a fixed ceiling or a fixed-split plateau conflates with a leak. The
	// pre-fix failure cannot pass: its climb is ~linear per request (~140 MB
	// per window), so it crosses the 520 MB backstop long before consecutive
	// window ratios flatten under 1.10, and eventually OOM-panics.
	mut ok := 0
	mut total := 0
	mut prev_kb := u64(0)
	mut converged := false
	mut last_kb := u64(0)
	for _ in 0 .. 7 {
		for _ in 0 .. 1000 {
			if one_get(port) {
				ok++
			}
		}
		total += 1000
		last_kb = rss_kb(pid)
		if last_kb == 0 {
			break // RSS unmeasurable; survival assertions below still hold
		}
		assert last_kb < 520 * 1024, 'heavy reactor RSS ${last_kb} KB after ${total} requests exceeds the 520 MB runaway backstop (#131/#71); the pre-adaptive-pacer repro reaches ~571 MB by 4000 requests and keeps climbing'
		if prev_kb > 0 && f64(last_kb) / f64(prev_kb) < 1.10 {
			converged = true
			break
		}
		prev_kb = last_kb
	}

	alive := os.execute('kill -0 ${pid} 2>/dev/null').exit_code == 0
	log := os.read_file('/tmp/cx_rss_heavy.log') or { '' }
	assert alive, 'heavy reactor died under ${total}-req load (likely the #131 OOM panic); served ${ok}/${total}; log: ${log}'
	assert ok * 100 >= total * 95, 'heavy reactor dropped too many requests: ${ok}/${total} ok; log: ${log}'
	if last_kb == 0 {
		eprintln('NOTE: RSS unmeasurable on this platform; survival assertions still hold')
		return
	}
	assert converged, 'heavy reactor RSS never plateaued: ${last_kb} KB after ${total} requests, still growing >=10% per 1000-req window — transients are not being reclaimed by construction (#131/#71)'
}

// The churn-gate OPT-IN must keep working (it is the ops escape hatch for a
// host-chosen collection pace, and builtin.gc_collect_if_churned needs a live
// consumer): the same heavy shape with CX_HTTP_GC_MB=1 pinned must stay bounded
// and serve traffic exactly like the default path.
fn test_reactor_rss_bounded_with_churn_gate_pinned() {
	port := rss_port() + 2
	prog := write_tmp_file('cx_rss_gate.cx', rss_heavy_server_prog(port))
	pid_s := os.execute('CX_HTTP_N=1 CX_HTTP_GC_MB=1 ${cx_bin()} --allow-all ${prog} >/tmp/cx_rss_gate.log 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	if pid <= 0 {
		eprintln('SKIP: could not spawn gate-pinned reactor server')
		return
	}
	defer {
		os.execute('kill -9 ${pid} 2>/dev/null')
	}

	mut up := false
	for _ in 0 .. 50 {
		if one_get(port) {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	if !up {
		log := os.read_file('/tmp/cx_rss_gate.log') or { '' }
		eprintln('SKIP: gate-pinned reactor never bound on ${port}; log: ${log}')
		return
	}

	mut ok := 0
	for _ in 0 .. 1000 {
		if one_get(port) {
			ok++
		}
	}

	alive := os.execute('kill -0 ${pid} 2>/dev/null').exit_code == 0
	log := os.read_file('/tmp/cx_rss_gate.log') or { '' }
	assert alive, 'gate-pinned reactor died under load; served ${ok}/1000; log: ${log}'
	assert ok >= 950, 'gate-pinned reactor dropped too many requests: ${ok}/1000 ok; log: ${log}'

	rkb := rss_kb(pid)
	if rkb == 0 {
		eprintln('NOTE: RSS unmeasurable on this platform; survival assertions still hold')
		return
	}
	assert rkb < 280 * 1024, 'gate-pinned reactor RSS ${rkb} KB exceeds the 280 MB ceiling — the CX_HTTP_GC_MB opt-in regressed'
}

// ── source: vcx/tests/http_request_env_isolation_test.v ──
// http_request_env_isolation_test.v — BEHAVIORAL gate for cx-private #317
// (per-request template-alias env: immutable template + copy-on-write).
//
// The dispatch path no longer deep-clones the listener's bindings+closures
// per request: the request env ALIASES the immutable listener-start template
// (bindings_shared/closures_shared) and realizes a private copy only on an
// actual request-scope write (cow_bindings/cow_closures). The §10.5 isolation
// contract must hold exactly as before: concurrent requests binding the SAME
// names (here: the handler's [?let] frame + the service-mode `request`
// binding) must never observe each other's values, and the shared template
// must never be mutated by any request.
//
// Both hot shapes are gated:
//   - handler mode (`[$http:serve url $handler]`) — the env stays aliased for
//     the request's whole life (the closure call frame is built fresh);
//   - service mode (`[?http-service]` resources) — the per-request `request`
//     write is the CoW trigger.
//
// Each request carries a unique path; every response must echo BOTH the
// template binding (proves the template is intact under concurrent load) and
// its own path (proves no cross-request bleed). Handlers sleep ~80ms so all
// in-flight requests genuinely overlap on the executor pool.

const iso_handler_port = 39051

const iso_service_port = 39052

const iso_closure_port = 39053

const iso_lambda_port = 39054

const iso_concurrency = 12

fn write_handler_fixture(dir string) string {
	prog := "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?const greeting "template-intact"]\n' +
		'[?def handler impure (\$req)\n' +
		'  [?let [= \$p [\$concat "" \$req/@path]]\n' +
		'   [?let [= \$z [?sleep 80ms]]\n' +
		'    [response status=200 [headers] [body [\$concat \$greeting ":" \$p]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${iso_handler_port}" handler {block: true}]\n'
	src := os.join_path(dir, 'iso_handler.cx')
	os.write_file(src, prog) or { panic('write: ${err}') }
	return src
}

fn write_service_fixture(dir string) string {
	prog := '[?const greeting "template-intact"]\n' +
		'[?http-service\n' +
		'   [name "iso-svc"]\n' +
		'   [on http]\n' +
		'   [port ${iso_service_port}]\n' +
		'   [block true]\n' +
		'   [bind-host "127.0.0.1"]\n' +
		'   [resource [GET "/*"]\n' +
		'     [?let [= \$p [\$concat "" \$request/@path]]\n' +
		'      [?let [= \$z [?sleep 80ms]]\n' +
		'       [response status=200 [body [\$concat \$greeting ":" \$p]]]]]]]\n'
	src := os.join_path(dir, 'iso_service.cx')
	os.write_file(src, prog) or { panic('write: ${err}') }
	return src
}

// write_closure_fixture gates the #333 closure-call analog: every call frame
// built by build_param_call_env ALIASES the closure's defining-scope bindings
// (CoW on first write) instead of copying them per call. Concurrent requests
// drive closure shapes that write into aliased frames:
//   - `shadowed`: its parameter SHADOWS the defining-scope const `greeting` —
//     the param bind is the CoW trigger; it must never write through to the
//     shared defining scope;
//   - `spin`: tail-recursive — every TCO trampoline hop rebuilds an aliased
//     frame with per-request values;
//   - `defgreet`: an omitted defaulted param whose default expression READS
//     the defining scope through the aliased call env.
// Every response must echo the intact template const BEFORE and AFTER the
// shadowing call, plus its own per-request values — never another request's.
fn write_closure_fixture(dir string) string {
	prog := "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?const greeting "template-intact"]\n' +
		'[?const depth 6]\n' +
		'[?def shadowed (\$greeting) [\$concat "shadow=" \$greeting]]\n' +
		'[?def spin (\$n \$acc) [?if [> \$n 0] [then [spin [- \$n 1] [\$concat \$acc "."]]] [else \$acc]]]\n' +
		'[?def defgreet (\$p \$suffix=\$greeting) [\$concat \$p "+" \$suffix]]\n' +
		'[?def handler impure (\$req)\n' +
		'  [?let [= \$p [\$concat "" \$req/@path]]\n' +
		'   [?let [= \$z [?sleep 80ms]]\n' +
		'    [response status=200 [headers] [body [\$concat \$greeting ":" \$p "|" [shadowed \$p] "|" [spin \$depth \$p] "|" [defgreet \$p] "|" \$greeting]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${iso_closure_port}" handler {block: true}]\n'
	src := os.join_path(dir, 'iso_closure.cx')
	os.write_file(src, prog) or { panic('write: ${err}') }
	return src
}

// write_lambda_fixture gates the #341 [?fn]-path analog of #333: a positional
// lambda whose defining scope carries bindings gets a call frame that ALIASES
// those bindings (invoke_positional_l, CoW on first write — the alias half of
// the alias-vs-pool hybrid). Concurrent requests drive the write-through
// risks on aliased lambda frames:
//   - `$shadow`: its parameter SHADOWS the defining-scope const `greeting` —
//     the captured/param bind is the CoW trigger; it must never write through
//     to the shared program scope;
//   - `$reader`: binds its param, then reads the defining-scope const THROUGH
//     the realized CoW frame (const value must survive the private copy).
// Every response must echo the intact template const BEFORE and AFTER the
// shadowing call, plus its own per-request values — never another request's.
fn write_lambda_fixture(dir string) string {
	prog := "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?const greeting "template-intact"]\n' +
		'[?const bump 3]\n' +
		'[?def handler impure (\$req)\n' +
		'  [?let [= \$p [\$concat "" \$req/@path]]\n' +
		'   [?let [= \$shadow [?fn (\$greeting) [\$concat "lshadow=" \$greeting]]]\n' +
		'    [?let [= \$reader [?fn (\$x) [\$concat \$x "+" \$greeting]]]\n' +
		'     [?let [= \$z [?sleep 80ms]]\n' +
		'      [response status=200 [headers] [body [\$concat \$greeting ":" \$p "|" [\$shadow \$p] "|" [\$reader \$p] "|" \$greeting]]]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${iso_lambda_port}" handler {block: true}]\n'
	src := os.join_path(dir, 'iso_lambda.cx')
	os.write_file(src, prog) or { panic('write: ${err}') }
	return src
}

// raw_get opens a fresh connection, sends GET `path`, and returns the raw
// response, '' on failure. One read carries the whole single-segment response
// (see http_slow_handler_isolation_test.v for why we do not read to EOF).
fn raw_get(port int, path string, read_ms i64) string {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return '' }
	defer {
		c.close() or {}
	}
	c.write_string('GET ${path} HTTP/1.1\r\nHost: t\r\nConnection: close\r\n\r\n') or { return '' }
	c.set_read_timeout(read_ms * time.millisecond)
	mut buf := []u8{len: 8192}
	n := c.read(mut buf) or { return '' }
	if n <= 0 {
		return ''
	}
	return buf[..n].bytestr()
}

fn wait_up(port int, probe string) bool {
	for _ in 0 .. 60 {
		r := raw_get(port, probe, 1000)
		if r.contains('200') {
			return true
		}
		time.sleep(250 * time.millisecond)
	}
	return false
}

fn start_server(src string) &os.Process {
	log := src + '.log'
	mut p := os.new_process('/bin/sh')
	// `exec` so signal_kill reaches the SERVER, not just the sh wrapper — a
	// failing lane must not leave a stray server false-greening later runs
	// on this test's fixed ports (the #355 masking mechanism).
	p.set_args(['-c', 'exec ${cx_bin()} --allow-net=127.0.0.1 ${os.quoted_path(src)} >${os.quoted_path(log)} 2>&1'])
	p.run()
	return p
}

fn fetch_one(port int, i int) string {
	return raw_get(port, '/req-${i}', 6000)
}

// assert_isolated fires `iso_concurrency` overlapping requests with unique
// paths and asserts every response echoes the intact template binding AND its
// own path — never another request's.
fn assert_isolated(port int, label string) {
	mut threads := []thread string{}
	for i in 0 .. iso_concurrency {
		threads << spawn fetch_one(port, i)
	}
	for i, t in threads {
		r := t.wait()
		want := 'template-intact:/req-${i}'
		assert r.contains('200'), '${label}: request ${i} failed: ${r}'
		assert r.contains(want), '${label}: request ${i} response does not carry its own isolated bindings (want "${want}"): ${r}'
	}
}

fn test_handler_mode_concurrent_binding_isolation() {
	dir := os.join_path(os.temp_dir(), 'cx_317_iso_h_${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	src := write_handler_fixture(dir)
	mut p := start_server(src)
	defer {
		p.signal_kill()
		p.close()
	}
	assert wait_up(iso_handler_port, '/warm'), 'handler serve did not come up on :${iso_handler_port}'
	// three overlapping waves: sustained concurrent same-name rebinding
	for _ in 0 .. 3 {
		assert_isolated(iso_handler_port, 'handler-mode')
	}
	os.rmdir_all(dir) or {} // success path only — a failing run leaves the log
}

// assert_closure_isolated fires overlapping requests and asserts each
// response carries the intact template const around the shadowing call plus
// all three per-request closure results — never another request's.
fn assert_closure_isolated(port int, label string) {
	mut threads := []thread string{}
	for i in 0 .. iso_concurrency {
		threads << spawn fetch_one(port, i)
	}
	for i, t in threads {
		r := t.wait()
		p := '/req-${i}'
		want := 'template-intact:${p}|shadow=${p}|${p}......|${p}+template-intact|template-intact'
		assert r.contains('200'), '${label}: request ${i} failed: ${r}'
		assert r.contains(want), '${label}: request ${i} closure-call frames not isolated (want "${want}"): ${r}'
	}
}

fn test_closure_call_concurrent_binding_isolation() {
	dir := os.join_path(os.temp_dir(), 'cx_333_iso_c_${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
