// ── source: vcx/tests/http_split_body_test.v ──
// http_split_body_test.v — #48: a POST whose body arrives in a SEPARATE TCP
// segment from the headers must NOT be seen as empty by the handler.
//
// picohttpparser's parse return covers only the request line + headers, not the
// body. The picoev read loop used to break as soon as the headers parsed and
// hand the request to the callback with whatever body bytes happened to already
// be buffered — empty when the body landed in a later segment (cold/rapid
// connections). The fix keeps reading until the full Content-Length body is
// buffered before invoking the callback.
//
// This test makes the race DETERMINISTIC: it writes the headers, flushes,
// sleeps so the server's first recv() sees only the headers, then writes the
// body as a second segment. The echo server must still see the full body.

fn cx_bin_sb() string {
	return testenv.cx_bin()
}

fn pick_port_sb() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26700 + int(salt)
}

// A `[$http:serve]` HANDLER-mode echo server — the picoev reactor path
// (listener_callback) that reads the body via picohttpparser. The handler
// echoes the request body verbatim. This is the path #48 reported against
// (NOT accept-iter, which reads the body synchronously via net_read_exact_buf).
fn echo_server_prog(port int) string {
	return '[?lib \'cx-stdlib/http\' :as http]\n' +
		'[?def h (\$req::element)\n' +
		'  [response status=200 [body [\$http:body-text \$req]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]\n'
}

// Send a POST with headers and body in two separate segments, with a gap so the
// server's first read observes only the headers. Returns the echoed body.
fn split_post(port int, body string) ?string {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return none }
	defer { c.close() or {} }
	head := 'POST /echo HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: ${body.len}\r\nConnection: close\r\n\r\n'
	c.write_string(head) or { return none }
	// Force the body into a distinct TCP segment, after the server has had a
	// chance to recv() just the headers.
	time.sleep(120 * time.millisecond)
	c.write_string(body) or { return none }

	c.set_read_timeout(4 * time.second)
	// Read until we have the full response: headers + a Content-Length body. We
	// parse the response's own Content-Length rather than reading to EOF so the
	// test doesn't wait on the server's idle timeout for the socket close.
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	mut want := -1
	mut head_end := -1
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		resp_so_far := raw.bytestr()
		if head_end < 0 {
			head_end = resp_so_far.index('\r\n\r\n') or { -1 }
			if head_end >= 0 {
				for line in resp_so_far[..head_end].split('\r\n') {
					if line.to_lower().starts_with('content-length:') {
						want = line.all_after(':').trim_space().int()
					}
				}
			}
		}
		if head_end >= 0 {
			have := raw.len - (head_end + 4)
			if want < 0 || have >= want {
				break
			}
		}
		if raw.len > 65536 {
			break
		}
	}
	resp := raw.bytestr()
	idx := resp.index('\r\n\r\n') or { return none }
	body_all := resp[idx + 4..]
	if want >= 0 && body_all.len >= want {
		return body_all[..want]
	}
	return body_all
}

fn test_split_segment_post_body_not_empty() {
	port := pick_port_sb()
	prog := os.join_path(os.temp_dir(), 'cx_sb_${os.getpid()}.cx')
	os.write_file(prog, echo_server_prog(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-sb.${port}.out'
	pid_s := os.execute('${cx_bin_sb()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx http server')
		return
	}
	pid := pid_s.output.trim_space()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
		os.rm(out_file) or {}
	}

	// Wait for the listener to come up.
	mut up := false
	for _ in 0 .. 50 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.close() or {}
		up = true
		break
	}
	assert up, 'cx echo server never came up on ${port}'

	// Run the split-segment POST several times — the bug was intermittent, so a
	// single pass could pass by luck. The body must echo back in full every time.
	expected := 'verb=greet actor=alice'
	for i in 0 .. 8 {
		got := split_post(port, expected) or {
			assert false, 'split POST #${i} got no response'
			return
		}
		assert got == expected, 'split POST #${i}: body lost — expected "${expected}", got "${got}"'
	}
}

// ── #838: the DIRECTIVE lane must see the request body too ───────────────────
// The test above covers `[$http:serve]` HANDLER mode. The `[?http-service]`
// `[resource]` lane had `raw_body` in scope in dispatch_request but passed
// `?cx.Node(none)` to build_request_node, so a directive resource saw
// `[body ()]` for EVERY real-socket request — a POST payload was unreachable,
// and with it any form submission or command post.
//
// code.md §10.3.3 states the `body` child normatively ("holds the parsed
// request body when `consumes=` permits"; the default `*/*` permits it), so
// this was a spec deviation rather than a design choice — unlike the
// neighbouring `[headers]` omission, which services.v documents as deliberate
// (the directive lane's auth is the `[auth …]` seam).
//
// It survived because the conformance fixtures for services
// (conformance/code.cxd program-svc-002 and friends) drive the IN-PROCESS lane
// through `[?test-service-client]`, which passes `opts.payload` as the body and
// was always correct. Only the real-socket path dropped it, and nothing
// exercised that path with a body.
//
// Reusing split_post covers the segmentation case on this lane for free.
fn directive_echo_server_prog(port int) string {
	return '[?http-service on=http port=${port} name="echo-directive"\n' +
		'  [bind-host "127.0.0.1"]\n' +
		'  [block true]\n' +
		'  [resource [post "/echo"]\n' +
		'    [response status=200 [body \$request/body]]]]\n'
}

// #838 (RULED): the directive lane must also see request HEADERS. §10.3.3
// states the `headers` child normatively; the lane left it empty on the
// rationale that a directive service's auth rides the `[auth …]` seam — which
// explains why headers were not needed for auth, not why a normative field
// should stay unpopulated. A session cookie is a header, so actor stamping
// cannot read its own principal without this.
//
// The handler echoes ONE named header's value, so the assertion is about a
// specific header arriving intact rather than about the collection's shape.
fn directive_header_server_prog(port int) string {
	return '[?http-service on=http port=${port} name="hdr-directive"\n' +
		'  [bind-host "127.0.0.1"]\n' +
		'  [block true]\n' +
		'  [resource [post "/echo"]\n' +
		'    [?let [= \$h [?for [in \$x \$request/headers/header]\n' +
		'                   [where [= \$x@name "X-Cx-Probe"]]\n' +
		'                   [yield [\$string \$x@value]]]]\n' +
		'      [response status=200 [body [\$concat "probe=" [\$first \$h]]]]]]]\n'
}

fn test_directive_resource_sees_request_headers() {
	port := pick_port_sb() + 2
	prog := os.join_path(os.temp_dir(), 'cx_838h_${os.getpid()}.cx')
	os.write_file(prog, directive_header_server_prog(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-838h.${port}.out'
	pid_s := os.execute('${cx_bin_sb()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx directive server')
		return
	}
	pid := pid_s.output.trim_space()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
		os.rm(out_file) or {}
	}

	mut up := false
	for _ in 0 .. 50 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.close() or {}
		up = true
		break
	}
	assert up, 'cx directive server never came up on ${port}'

	mut c := net.dial_tcp('127.0.0.1:${port}') or {
		assert false, 'could not dial ${port}'
		return
	}
	defer { c.close() or {} }
	body := 'x=1'
	req := 'POST /echo HTTP/1.1\r\nHost: 127.0.0.1\r\nX-Cx-Probe: session-cookie-stand-in\r\n' +
		'Content-Length: ${body.len}\r\nConnection: close\r\n\r\n${body}'
	c.write_string(req) or {
		assert false, 'write failed'
		return
	}
	c.set_read_timeout(4 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		if raw.len > 65536 {
			break
		}
	}
	resp := raw.bytestr()
	assert resp.contains('probe=session-cookie-stand-in'), 'directive resource did not see the request header; got: ${resp}'
}

fn test_directive_resource_sees_post_body() {
	port := pick_port_sb() + 1
	prog := os.join_path(os.temp_dir(), 'cx_838_${os.getpid()}.cx')
	os.write_file(prog, directive_echo_server_prog(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-838.${port}.out'
	pid_s := os.execute('${cx_bin_sb()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx directive server')
		return
	}
	pid := pid_s.output.trim_space()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
		os.rm(out_file) or {}
	}

	mut up := false
	for _ in 0 .. 50 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.close() or {}
		up = true
		break
	}
	assert up, 'cx directive server never came up on ${port}'

	// A form-encoded payload, since that is what a projected form submits.
	expected := 'customer=Ada+Lovelace&qty=3&note=R+%26+D'
	for i in 0 .. 4 {
		got := split_post(port, expected) or {
			assert false, 'directive POST #${i} got no response'
			return
		}
		assert got == expected, 'directive POST #${i}: [?http-service] resource did not see the body — expected "${expected}", got "${got}"'
	}
}

// ── source: vcx/tests/http_sse_headers_test.v ──
// http_sse_headers_test.v — #661: `sse-connect` must send `opts.headers` on the
// subscription GET. `headers` is a parent client key (http.md §3 table) and
// §3.6 specifies sse-connect's opts as "plus the parent client keys", but the
// verb hand-built its request line and never consulted them — so a caller could
// not authenticate a stream at all. xap_identity_model §4.12 requires
// `GET /stream` to carry the same three XSP proof headers as every other
// request; they had nowhere to ride.
//
// The raw-socket server CAPTURES the request head to a file, so these lanes
// assert what actually reached the wire rather than what the client believed it
// sent.
//   1. caller headers appear on the GET
//   2. managed fields are ignored, not errors (§4.6) — a caller-supplied Host
//      does not displace the URL's, and the stream still opens
//   3. CR/LF in a header is request-splitting → CXER4531

fn hdr_cx_binary() string {
	return testenv.cx_bin()
}

fn hdr_salt() int {
	return int((u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100)
}

fn hdr_write_tmp(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// hdr_capture_server accepts one connection, writes the request head to
// `cap_path`, answers with a minimal event stream, and exits.
fn hdr_capture_server(mut l net.TcpListener, cap_path string) {
	mut c := l.accept() or {
		l.close() or {}
		return
	}
	mut req := []u8{}
	mut hb := []u8{len: 1}
	for {
		n := c.read(mut hb) or { break }
		if n <= 0 {
			break
		}
		req << hb[0]
		if req.len >= 4 && req#[-4..].bytestr() == '\r\n\r\n' {
			break
		}
	}
	os.write_file(cap_path, req.bytestr()) or {}
	c.write_string('HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\n\r\n') or {}
	c.write_string('id: 1\ndata: alpha\n\n') or {}
	time.sleep(150 * time.millisecond)
	c.close() or {}
	l.close() or {}
}

// 1 + 2: caller headers reach the wire; a managed field is ignored, not fatal.
fn test_sse_connect_sends_opts_headers() {
	port := 26200 + hdr_salt()
	mut listener := net.listen_tcp(.ip, '127.0.0.1:${port}') or {
		eprintln('SKIP: cannot bind 127.0.0.1:${port}: ${err}')
		return
	}
	listener.set_accept_timeout(5 * time.second)
	cap_path := os.join_path(os.temp_dir(), 'cx-sse-hdrs.${port}.head')
	os.rm(cap_path) or {}
	srv := spawn hdr_capture_server(mut listener, cap_path)

	// XSP-* are the §4.12 proof headers this defect blocked; Host is the
	// managed-field probe (§4.6: ignored and overwritten, never an error).
	prog := hdr_write_tmp('cx_sse_hdrs.cx', '[?lib \'cx-stdlib/http\' :as http]\n' +
		'[?let [= \$src [\$http:sse-connect "http://127.0.0.1:${port}/stream"\n' +
		'        {reconnect: false, headers: {XSP-Channel: "abc123", XSP-Counter: "1",\n' +
		'         XSP-Proof: "cHJvb2Y=", Host: "evil.example"}}]]\n' +
		'  [?for [in \$ev [\$http:sse-events \$src]] [yield \$ev]]]\n')
	res := os.execute('${hdr_cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()

	head := os.read_file(cap_path) or { '' }
	assert head.contains('XSP-Channel: abc123'), 'sse-connect dropped opts.headers (#661); request head was: ${head}'
	assert head.contains('XSP-Counter: 1'), 'sse-connect dropped XSP-Counter; head: ${head}'
	assert head.contains('XSP-Proof: cHJvb2Y='), 'sse-connect dropped XSP-Proof; head: ${head}'
	// §4.6: the URL's Host wins and the caller's is silently dropped
	assert head.contains('Host: 127.0.0.1'), 'the URL Host was not sent; head: ${head}'
	assert !head.contains('evil.example'), 'a caller-supplied managed Host reached the wire; head: ${head}'
	// the stream still opens and reads — a managed field is not an error
	assert res.output.contains('alpha'), 'the stream did not read after headers were applied; got: ${res.output}'
}

// 3: CR/LF in a caller header is request-splitting, refused (CXER4531).
fn test_sse_connect_rejects_header_injection() {
	port := 26300 + hdr_salt()
	mut listener := net.listen_tcp(.ip, '127.0.0.1:${port}') or {
		eprintln('SKIP: cannot bind 127.0.0.1:${port}: ${err}')
		return
	}
	listener.set_accept_timeout(2 * time.second)
	cap_path := os.join_path(os.temp_dir(), 'cx-sse-inject.${port}.head')
	os.rm(cap_path) or {}
	srv := spawn hdr_capture_server(mut listener, cap_path)

	prog := hdr_write_tmp('cx_sse_inject.cx', '[?lib \'cx-stdlib/http\' :as http]\n' +
		'[?let [= \$src [\$http:sse-connect "http://127.0.0.1:${port}/stream"\n' +
		'        {reconnect: false, headers: {X-Bad: "a\\r\\nX-Injected: yes"}}]]\n' +
		'  [out \$src]]\n')
	res := os.execute('${hdr_cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()

	captured := os.read_file(cap_path) or { '' }
	assert res.output.contains('CXER4531'), 'a CR/LF header was not refused with CXER4531; got: ${res.output}'
	assert !captured.contains('X-Injected'), 'the split header reached the wire; head: ${captured}'
}

// ── source: vcx/tests/http_sse_peer_rst_survival_test.v ──
// http_sse_peer_rst_survival_test.v — a server must survive a subscriber that
// vanishes between pushes.
//
// The failure this pins: SSE holds fds open and pushes to them asynchronously
// (`cx_sse_topic_publish` / `xap_sse_push` / `send_all` write with raw
// C.write). A subscriber that disconnects sends FIN; the NEXT push into that
// fd is accepted by the kernel but answered with RST; the push AFTER that
// raises SIGPIPE — whose default action terminates the process SILENTLY (no V
// panic, no crash report; the marine helm died this way every few minutes
// under client reconnect churn). The fix ignores SIGPIPE at the listener
// (transport.picoev new() + SO_NOSIGPIPE on accepted fds), so the write
// reports EPIPE and the publish path drops the fd.
//
// Asserts:
//   1. subscriber closes → two pushes (FIN-write, then RST-write) → the server
//      PROCESS is still alive and answers /ping.
//   2. the dead fd was reaped: a later publish reports pushed=0.

fn cx_bin_rst() string {
	return testenv.cx_bin()
}

fn pick_port_rst() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 29300 + int(salt)
}

fn rst_server_prog(port int) string {
	return "[?lib 'cx-stdlib/http' :as http]\n" +
		'[?def h impure (\$req)\n' +
		'  [?let [= \$p [\$text \$req@path]]\n' +
		'    [?if [= \$p "/events"]\n' +
		'      [then [sse-subscribe topic="t" [event data="hello"]]]\n' +
		'      [else [?if [= \$p "/push"]\n' +
		'        [then [?let [= \$n [\$http:sse-publish "t" [event data="beat"]]]\n' +
		'                [response status=200 [body [\$concat "pushed=" [\$text \$n]]]]]]\n' +
		'        [else [response status=200 [body "pong"]]]]]]]]\n' +
		'[\$http:serve "tcp://127.0.0.1:${port}" \$h {block: true}]\n'
}

fn rst_get(port int, path string) string {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return '' }
	defer { c.close() or {} }
	c.write_string('GET ${path} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n') or { return '' }
	c.set_read_timeout(4 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		if raw.len > 65536 {
			break
		}
	}
	return raw.bytestr()
}

fn test_sse_peer_rst_survival() {
	port := pick_port_rst()
	prog := os.join_path(os.temp_dir(), 'cx_sse_rst_${os.getpid()}.cx')
	os.write_file(prog, rst_server_prog(port)) or { panic('write: ${err}') }
	defer { os.rm(prog) or {} }
	out_file := '/tmp/cx-sse-rst.${port}.out'
	pid_s := os.execute('${cx_bin_rst()} --allow-net ${prog} >${out_file} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx sse server')
		return
	}
	pid := pid_s.output.trim_space()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
		os.rm(out_file) or {}
	}

	mut up := false
	for _ in 0 .. 50 {
		mut c := net.dial_tcp('127.0.0.1:${port}') or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.close() or {}
		up = true
		break
	}
	assert up, 'cx sse server never came up on ${port}'

	// subscribe, confirm registration via the initial frame, then VANISH
	mut a := net.dial_tcp('127.0.0.1:${port}') or {
		assert false, 'could not open SSE client'
		return
	}
	a.write_string('GET /events HTTP/1.1\r\nHost: x\r\n\r\n') or {}
	a.set_read_timeout(4 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	for {
		n := a.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		if raw.bytestr().contains('data: hello') {
			break
		}
	}
	assert raw.bytestr().contains('data: hello'), 'subscriber never registered'
	a.close() or {}

	// push #1 lands on the FIN'd socket (kernel accepts, peer answers RST);
	// push #2 writes into the RST'd socket — pre-fix this is the SIGPIPE kill.
	rst_get(port, '/push')
	time.sleep(200 * time.millisecond)
	rst_get(port, '/push')
	time.sleep(200 * time.millisecond)

	// (1) the server process survived and still serves
	alive := os.execute('kill -0 ${pid}')
	assert alive.exit_code == 0, 'server process died after pushing to an RST\'d subscriber (SIGPIPE regression)'
	pong := rst_get(port, '/ping')
	assert pong.contains('pong'), 'server not serving after RST push: "${pong}"'

	// (2) the dead fd was reaped from the topic — a fresh publish reaches 0
	final := rst_get(port, '/push')
	assert final.contains('pushed=0'), 'dead subscriber fd not reaped: "${final}"'
}

// ── source: vcx/tests/http_sse_test.v ──
// http_sse_test.v — the §3.6 SSE [event] SYMMETRY INVARIANT
// (spec/02-working/stdlib_http.md §3.6, §10): what the server frames with
// `send-event` parses back EQUAL on the client via `sse-events`. Both
// halves share ONE pure framing codec (code.http_sse_frame_event /
// code.http_sse_parse_event), so the round-trip holds by construction —
// this test pins both the exact wire format and the value round-trip.

fn ev_attr(e cx.Element, name string) string {
	for a in e.attrs {
		if a.name == name {
			return cx.scalar_value_str_public(a.value)
		}
	}
	return '<<absent>>'
}

fn mk_event(attrs []cx.Attribute) cx.Element {
	return cx.Element{
		name:  'event'
		attrs: attrs
	}
}

// ── exact canonical wire format ──────────────────────────────────────
fn test_sse_frame_canonical_wire() {
	ev := mk_event([
		cx.Attribute{ name: 'id', value: cx.ScalarValue('42') },
		cx.Attribute{ name: 'event', value: cx.ScalarValue('order-updated') },
		cx.Attribute{ name: 'data', value: cx.ScalarValue('hello\nworld') },
		cx.Attribute{ name: 'retry', value: cx.ScalarValue(i64(3000)) },
	])
	framed := code.http_sse_frame_event(ev)
	wire := if framed is cx.ScalarNode {
		v := framed.value
		if v is string { v } else { '' }
	} else {
		''
	}
	expected := 'id: 42\nevent: order-updated\ndata: hello\ndata: world\nretry: 3000\n\n'
	assert wire == expected, 'SSE wire mismatch:\n got: ${wire}\nwant: ${expected}'
}

// ── the symmetry invariant: frame → parse is identity ────────────────
fn test_sse_frame_parse_round_trip() {
	cases := [
		mk_event([
			cx.Attribute{ name: 'id', value: cx.ScalarValue('1') },
			cx.Attribute{ name: 'event', value: cx.ScalarValue('ping') },
			cx.Attribute{ name: 'data', value: cx.ScalarValue('payload') },
		]),
		mk_event([
			cx.Attribute{ name: 'data', value: cx.ScalarValue('only-data') },
		]),
		mk_event([
			cx.Attribute{ name: 'id', value: cx.ScalarValue('99') },
			cx.Attribute{ name: 'data', value: cx.ScalarValue('multi\nline\ndata') },
			cx.Attribute{ name: 'retry', value: cx.ScalarValue(i64(5000)) },
		]),
	]
	for ev in cases {
		framed := code.http_sse_frame_event(ev)
		wire := if framed is cx.ScalarNode {
			v := framed.value
			if v is string { v } else { '' }
		} else {
			assert false, 'frame returned a non-string (err?) for ${ev}'
			''
		}
		parsed := code.http_sse_parse_event(wire) or {
			assert false, 'parse failed for wire: ${wire}'
			return
		}
		// every attribute the server wrote parses back equal on the client
		assert ev_attr(parsed, 'id') == ev_attr(ev, 'id'), 'id drift: ${wire}'
		assert ev_attr(parsed, 'event') == ev_attr(ev, 'event'), 'event drift: ${wire}'
		assert ev_attr(parsed, 'data') == ev_attr(ev, 'data'), 'data drift: ${wire}'
		assert ev_attr(parsed, 'retry') == ev_attr(ev, 'retry'), 'retry drift: ${wire}'
	}
}

// ── comment / heartbeat frames are consumed silently (→ none) ────────
fn test_sse_parse_comment_only_is_none() {
	if _ := code.http_sse_parse_event(': keep-alive comment\n') {
		assert false, 'a comment-only frame must parse to none (silently consumed)'
	}
}

// ── empty [event] → CXER4539; CR/LF in id/event → CXER4531 ───────────
fn test_sse_frame_validation() {
	empty := code.http_sse_frame_event(mk_event([]))
	assert empty is cx.Element && (empty as cx.Element).name == 'err',
		'empty [event] must frame to an err'
	crlf := code.http_sse_frame_event(mk_event([
		cx.Attribute{ name: 'id', value: cx.ScalarValue('a\nb') },
		cx.Attribute{ name: 'data', value: cx.ScalarValue('x') },
	]))
	assert crlf is cx.Element && (crlf as cx.Element).name == 'err',
		'CR/LF in id must frame to an err'
}

// ── HOSTILE (audit): CR in DATA breaks the symmetry invariant ────────
// A `data` value ending in CR was framed verbatim then silently stripped by
// the parser's trim_right('\r'), so frame→parse was NOT identity. CR in data
// must now be rejected (CXER4531), the same as id/event; LF (the legitimate
// multi-line separator) still round-trips.
fn test_sse_data_cr_rejected() {
	cr := code.http_sse_frame_event(mk_event([
		cx.Attribute{ name: 'data', value: cx.ScalarValue('payload\r') },
	]))
	assert cr is cx.Element && (cr as cx.Element).name == 'err' &&
		ev_attr(cr as cx.Element, 'code') == 'cx-err:CXER4531',
		'CR in data must frame to CXER4531'
	// LF-bearing multi-line data still frames + round-trips (symmetry holds)
	ml := code.http_sse_frame_event(mk_event([
		cx.Attribute{ name: 'data', value: cx.ScalarValue('a\nb\nc') },
	]))
	assert !(ml is cx.Element && (ml as cx.Element).name == 'err'),
		'multi-line (LF) data must still frame'
}

// ── HOSTILE (audit): an unknown-attr-only [event] has nothing to send ──
// `[event foo="bar"]` carries no SSE field; the prior `&& attrs.len == 0`
// guard let it slip through and frame an empty wire. It must fault (CXER4539).
fn test_sse_unknown_attr_event_is_empty() {
	e := code.http_sse_frame_event(mk_event([
		cx.Attribute{ name: 'foo', value: cx.ScalarValue('bar') },
	]))
	assert e is cx.Element && (e as cx.Element).name == 'err' &&
		ev_attr(e as cx.Element, 'code') == 'cx-err:CXER4539',
		'an event with only unknown attrs must fault CXER4539'
}

// ── HOSTILE (audit): malformed-frame detection (the CXER4551 gate) ────
// sse-events used to `or { continue }` past every unparseable frame, so the
// declared CXER4551 was unreachable. A frame carrying an embedded CR (a byte
// our framer never emits) is now detected as malformed; sse-events raises
// CXER4551 on it instead of swallowing it. A clean / comment-only frame is
// NOT malformed.
fn test_sse_block_malformed_detection() {
	assert code.http_sse_block_malformed('data: a\rb\ndata: c'),
		'an embedded CR must be detected as a malformed frame'
	assert !code.http_sse_block_malformed('data: a\ndata: b'),
		'a clean LF-separated frame is not malformed'
	assert !code.http_sse_block_malformed(': heartbeat comment'),
		'a comment/heartbeat frame is not malformed'
	assert !code.http_sse_block_malformed('data: trailing\r'),
		'a trailing CR (CRLF line ending) is not malformed'
}
